### Example 1: Stack Using List
```python
class Stack:
    """LIFO Stack using list"""
    def __init__(self):
        self._data = []

    def push(self, item):
        self._data.append(item)      # O(1) amortized

    def pop(self):
        if self.is_empty():
            raise IndexError("Stack underflow")
        return self._data.pop()      # O(1) — removes last!

    def peek(self):
        return self._data[-1] if self._data else None

    def is_empty(self): return len(self._data) == 0
    def size(self):     return len(self._data)
    def __repr__(self): return f"Stack({self._data})"

# Application: balanced parentheses checker
def is_balanced(s):
    stack  = Stack()
    pairs  = {')':'(', ']':'[', '}':'{'}
    for ch in s:
        if ch in '([{':
            stack.push(ch)
        elif ch in ')]}':
            if stack.is_empty() or stack.pop() != pairs[ch]:
                return False
    return stack.is_empty()

tests = ["(())", "([{}])", "(()", "({[]})", ")("]
for t in tests:
    print(f"  '{t}': {'✅ Balanced' if is_balanced(t) else '❌ Unbalanced'}")

# Application: function call stack simulation
def eval_rpn(tokens):
    """Evaluate Reverse Polish Notation using stack"""
    stack = Stack()
    ops   = {'+': lambda a,b: a+b, '-': lambda a,b: a-b,
             '*': lambda a,b: a*b, '/': lambda a,b: a/b}
    for token in tokens:
        if token in ops:
            b, a = stack.pop(), stack.pop()
            stack.push(ops[token](a, b))
        else:
            stack.push(float(token))
    return stack.pop()

# 3 4 + 2 * = (3+4)*2 = 14
print(f"\nRPN '3 4 + 2 *' = {eval_rpn(['3','4','+','2','*']):.0f}")
```

### Example 2: Queue and Why to Use `deque`
```python
from collections import deque
import time

# ❌ Queue with list — pop(0) is O(n)!
class SlowQueue:
    def __init__(self):
        self._data = []
    def enqueue(self, item): self._data.append(item)
    def dequeue(self): return self._data.pop(0)   # O(n)!!
    def __len__(self): return len(self._data)

# ✅ Queue with deque — O(1) on both ends!
class FastQueue:
    def __init__(self):
        self._data = deque()
    def enqueue(self, item): self._data.append(item)       # O(1)
    def dequeue(self):       return self._data.popleft()   # O(1)!
    def peek(self):          return self._data[0] if self._data else None
    def __len__(self):       return len(self._data)

# Benchmark
N = 10000
slow_q = SlowQueue()
fast_q = FastQueue()

t = time.time()
for i in range(N): slow_q.enqueue(i)
for i in range(N): slow_q.dequeue()
slow_time = time.time() - t

t = time.time()
for i in range(N): fast_q.enqueue(i)
for i in range(N): fast_q.dequeue()
fast_time = time.time() - t

print(f"Slow (list pop(0)): {slow_time:.4f}s")
print(f"Fast (deque):       {fast_time:.4f}s")
print(f"Speedup: {slow_time/fast_time:.1f}x")

# BFS using deque queue
def bfs(graph, start):
    """Breadth-First Search using deque"""
    visited = []
    queue   = deque([start])
    seen    = {start}

    while queue:
        node  = queue.popleft()
        visited.append(node)
        for neighbor in graph.get(node, []):
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append(neighbor)
    return visited

graph = {"A":["B","C"], "B":["D","E"], "C":["F"], "D":[], "E":["F"], "F":[]}
print(f"\nBFS from A: {bfs(graph, 'A')}")
```

### Example 3: Deque — Double-Ended Queue
```python
from collections import deque

# deque supports O(1) append/pop on BOTH ends!
dq = deque([1, 2, 3, 4, 5])

dq.append(6)        # Add right: [1,2,3,4,5,6]
dq.appendleft(0)    # Add left: [0,1,2,3,4,5,6]
dq.pop()            # Remove right: 6 → [0,1,2,3,4,5]
dq.popleft()        # Remove left: 0 → [1,2,3,4,5]

# maxlen — fixed-size sliding window!
recent = deque(maxlen=3)
for i in range(7):
    recent.append(i)
    print(f"  Added {i}: {list(recent)}")
# Auto-removes oldest when full!

# Sliding window maximum using deque
def sliding_window_max(nums, k):
    """Find maximum in each window of size k — O(n) using deque"""
    dq      = deque()  # Stores indices
    result  = []
    for i, n in enumerate(nums):
        # Remove elements outside window
        while dq and dq[0] < i - k + 1:
            dq.popleft()
        # Remove smaller elements from right
        while dq and nums[dq[-1]] < n:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result

prices = [3,1,2,5,8,4,6,7,2,9]
print(f"\nPrices: {prices}")
print(f"Max in window of 3: {sliding_window_max(prices, 3)}")
```
